/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { computeRegions } from './regions.js'

function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

async function readStdinAsync() {
  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  return Buffer.concat(chunks.map(c => (Buffer.isBuffer(c) ? c : Buffer.from(c)))).toString('utf8')
}

function main(mode, input) {
  const lines = splitLines(input)
  const parts = []
  let current = []
  for (const line of lines) {
    if (line === '%%%') {
      parts.push(current)
      current = []
    } else {
      current.push(line)
    }
  }
  parts.push(current)

  if (parts.length !== 3) {
    fail('expected three parts separated by %%%')
  }

  const [mine, base, theirs] = parts
  const regions = computeRegions(mine, base, theirs)

  const out = []
  let conflict = false

  for (const region of regions) {
    if (region.type === 'conflict') {
      conflict = true
    }
  }

  if (mode === 'regions') {
    for (const region of regions) {
      if (region.type === 'conflict') {
        out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
      } else {
        out.push(`${region.type} ${region.lines.length}`)
      }
    }
  } else {
    for (const region of regions) {
      if (region.type === 'conflict') {
        out.push('<<<<<<< mine')
        out.push(...region.mine)
        if (mode === 'merge') {
          out.push('||||||| base')
          out.push(...region.base)
        }
        out.push('=======')
        out.push(...region.theirs)
        out.push('>>>>>>> theirs')
      } else {
        out.push(...region.lines)
      }
    }
  }

  const text = out.length > 0 ? out.join('\n') + '\n' : ''
  process.stdout.write(text)
  process.exit(conflict ? 1 : 0)
}

const argv = process.argv.slice(2)
if (argv.length !== 1 || !['merge', 'merge2', 'regions'].includes(argv[0])) {
  fail('usage: cli.js merge|merge2|regions')
}

readStdinAsync().then(input => main(argv[0], input))
"}

