const ADDR_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

export function colToNum(letters) {
  let result = 0
  for (const ch of letters) {
    result = result * 26 + (ch.charCodeAt(0) - 64)
  }
  return result
}

export function numToCol(num) {
  let s = ''
  while (num > 0) {
    const rem = (num - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    num = Math.floor((num - 1) / 26)
  }
  return s
}

// Parses an address token (any case). Returns {col, row} or null if it is
// not a valid, addressable cell address.
export function parseAddress(str) {
  const m = ADDR_RE.exec(str)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col = colToNum(m[1].toUpperCase())
  return { col, row }
}

export function addressKeyStr(col, row) {
  return `${numToCol(col)}${row}`
}
"}

