import { GrammarError } from './errors.js'

const OPS2 = ['<=', '>=', '<>']
const OPS1 = '^*/+-=<>'

export function tokenize(text) {
  const tokens = []
  let i = 0
  const n = text.length
  while (i < n) {
    const c = text[i]
    if (c === ' ' || c === '\t') { i++; continue }
    if (c === '(') { tokens.push({ type: '(' }); i++; continue }
    if (c === ')') { tokens.push({ type: ')' }); i++; continue }
    if (c === ',') { tokens.push({ type: ',' }); i++; continue }
    if (c === ':') { tokens.push({ type: ':' }); i++; continue }
    const two = text.slice(i, i + 2)
    if (OPS2.includes(two)) { tokens.push({ type: 'op', value: two }); i += 2; continue }
    if (OPS1.includes(c)) { tokens.push({ type: 'op', value: c }); i++; continue }
    if (c >= '0' && c <= '9') {
      let j = i
      while (j < n && text[j] >= '0' && text[j] <= '9') j++
      if (text[j] === '.') {
        let k = j + 1
        let hasDigit = false
        while (k < n && text[k] >= '0' && text[k] <= '9') { k++; hasDigit = true }
        if (hasDigit) {
          tokens.push({ type: 'number', value: text.slice(i, k) })
          i = k
          continue
        }
      }
      tokens.push({ type: 'number', value: text.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      let j = i + 1
      while (j < n && /[A-Za-z]/.test(text[j])) j++
      while (j < n && text[j] >= '0' && text[j] <= '9') j++
      tokens.push({ type: 'word', value: text.slice(i, j) })
      i = j
      continue
    }
    throw new GrammarError(`unexpected character ${c}`)
  }
  tokens.push({ type: 'eof' })
  return tokens
}
"}

