{"file_path":"./src/cycle.js","content":"import { CycleError } from './errors.js'

/**
 * Finds the first cycle a depth-first search finds, starting from each task
 * in ascending name order and walking each task's dependencies in ascending
 * name order. Returns the cycle as an array of names, from the re-entered
 * task through the search stack, back to that task; or null if acyclic.
 */
export function findCycle(names, deps) {
  const color = new Map()
  for (const name of names) color.set(name, 0)
  const stack = []

  function dfs(node) {
    color.set(node, 1)
    stack.push(node)
    const dependencies = deps.get(node) || []
    for (const dep of dependencies) {
      const state = color.get(dep)
      if (state === 1) {
        const idx = stack.indexOf(dep)
        return stack.slice(idx).concat(dep)
      }
      if (state === 0) {
        const found = dfs(dep)
        if (found) return found
      }
    }
    color.set(node, 2)
    stack.pop()
    return null
  }

  for (const name of names) {
    if (color.get(name) === 0) {
      const found = dfs(name)
      if (found) return found
    }
  }
  return null
}

/** Throws CycleError if the graph has a cycle. */
export function checkAcyclic(names, deps) {
  const cycle = findCycle(names, deps)
  if (cycle) throw new CycleError(cycle)
}
"}

{"file_path":"./src/schedule.js","content":"/**
 * Computes, for every task, its start, finish and wave depth, plus the
 * overall total (unlimited-worker makespan). Assumes the graph is acyclic.
 *
 * A task's start is the greatest finish of its dependencies, or 0 when it
 * has none; its finish is its start plus its cost. A task's depth is 0 when
 * it has no dependency, and 1 + the greatest depth of its dependencies
 * otherwise.
 */
export function computeSchedule(names, cost, deps) {
  const start = new Map()
  const finish = new Map()
  const depth = new Map()

  // names is already in an order where dependencies can be resolved by
  // memoized recursion, since the graph is acyclic.
  function compute(name) {
    if (finish.has(name)) return
    const dependencies = deps.get(name) || []
    let s = 0
    let d = 0
    for (const dep of dependencies) {
      compute(dep)
      if (finish.get(dep) > s) s = finish.get(dep)
      if (depth.get(dep) + 1 > d) d = depth.get(dep) + 1
    }
    start.set(name, s)
    finish.set(name, s + cost.get(name))
    depth.set(name, d)
  }

  for (const name of names) compute(name)

  let total = 0
  for (const name of names) {
    if (finish.get(name) > total) total = finish.get(name)
  }

  return { start, finish, depth, total }
}

/**
 * Groups task names into waves by depth, each wave's names sorted ascending.
 */
export function computeWaves(names, depth) {
  const waves = []
  for (const name of names) {
    const d = depth.get(name)
    if (!waves[d]) waves[d] = []
    waves[d].push(name)
  }
  for (const wave of waves) {
    if (wave) wave.sort()
  }
  return waves
}
"}

