{"file_path":"./src/pack.js","content":"/**
 * Computes each task's priority: the cost of the longest chain that begins
 * at it, counting its own cost and then the costs down to any task that
 * nothing depends on (i.e. following the reverse-dependency edges toward a
 * task with no dependents).
 */
function computePriorities(names, cost, deps) {
  const dependents = new Map()
  for (const name of names) dependents.set(name, [])
  for (const [name, dependencyList] of deps) {
    for (const dep of dependencyList) {
      dependents.get(dep).push(name)
    }
  }

  const priority = new Map()

  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const dependent of dependents.get(name)) {
      const p = compute(dependent)
      if (p > best) best = p
    }
    const value = cost.get(name) + best
    priority.set(name, value)
    return value
  }

  for (const name of names) compute(name)
  return priority
}

/**
 * Simulates the build graph on the given number of workers, following the
 * greedy priority rule. Assumes the graph is acyclic. Returns
 * { workerRuns: Array<Array<{ name, start, finish }>>, makespan }.
 */
export function packSchedule(names, cost, deps, workerCount) {
  const priority = computePriorities(names, cost, deps)

  const started = new Set()
  const finish = new Map()
  const workerRuns = []
  const workerLastFinish = []
  for (let w = 0; w < workerCount; w++) {
    workerRuns.push([])
    workerLastFinish.push(0)
  }

  const remaining = new Set(names)

  function isReady(name, currentTime) {
    const dependencyList = deps.get(name) || []
    for (const dep of dependencyList) {
      if (!finish.has(dep) || finish.get(dep) > currentTime) return false
    }
    return true
  }

  function pickBest(readyList) {
    let best = null
    for (const name of readyList) {
      if (best === null) {
        best = name
        continue
      }
      const p = priority.get(name)
      const bestP = priority.get(best)
      if (p > bestP || (p === bestP && name < best)) {
        best = name
      }
    }
    return best
  }

  let currentTime = 0

  while (remaining.size > 0) {
    for (;;) {
      const freeWorkers = []
      for (let w = 0; w < workerCount; w++) {
        if (workerLastFinish[w] <= currentTime) freeWorkers.push(w)
      }
      if (freeWorkers.length === 0) break

      const readyList = []
      for (const name of remaining) {
        if (isReady(name, currentTime)) readyList.push(name)
      }
      if (readyList.length === 0) break

      const chosenTask = pickBest(readyList)
      const chosenWorker = freeWorkers[0]

      const start = currentTime
      const taskFinish = start + cost.get(chosenTask)
      workerRuns[chosenWorker].push({ name: chosenTask, start, finish: taskFinish })
      workerLastFinish[chosenWorker] = taskFinish
      finish.set(chosenTask, taskFinish)
      started.add(chosenTask)
      remaining.delete(chosenTask)
    }

    if (remaining.size === 0) break

    let nextTime = Infinity
    for (let w = 0; w < workerCount; w++) {
      if (workerLastFinish[w] > currentTime && workerLastFinish[w] < nextTime) {
        nextTime = workerLastFinish[w]
      }
    }
    currentTime = nextTime
  }

  let makespan = 0
  for (const f of finish.values()) {
    if (f > makespan) makespan = f
  }

  return { workerRuns, makespan }
}
"}

