{"file_path":"src/parse.js","content":"import { ElectionError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

/**
 * Parses an election from raw standard input text. Returns
 * `{ candidates, ballots }` where `candidates` is the array of declared
 * candidate names in declaration order, and `ballots` is an array of
 * `{ count, names }` objects, `names` being the ranked preference list.
 * Throws `ElectionError` on any invalid input.
 */
export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidatesDeclared = false
  let candidateSet = new Set()
  let candidateOrder = []
  let sawBallot = false
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidatesDeclared || sawBallot) {
        throw new ElectionError('candidates must be declared once, before any ballot', lineNum)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ElectionError('expected candidates <name>...', lineNum)
      }
      const seen = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ElectionError(`invalid candidate name ${name}`, lineNum)
        }
        if (seen.has(name)) {
          throw new ElectionError(`candidate ${name} is declared twice`, lineNum)
        }
        seen.add(name)
      }
      candidateSet = seen
      candidateOrder = names
      candidatesDeclared = true
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        throw new ElectionError('candidates must be declared once, before any ballot', lineNum)
      }
      sawBallot = true
      const rest = tokens.slice(1)
      if (rest.length < 2) {
        throw new ElectionError('expected ballot <count> <candidate>...', lineNum)
      }
      const countStr = rest[0]
      if (!COUNT_RE.test(countStr)) {
        throw new ElectionError('count must be a positive integer', lineNum)
      }
      const count = Number(countStr)
      const names = rest.slice(1)
      const seenInBallot = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ElectionError(`unknown candidate ${name}`, lineNum)
        }
        if (seenInBallot.has(name)) {
          throw new ElectionError(`candidate ${name} is repeated`, lineNum)
        }
        seenInBallot.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw new ElectionError(`unknown directive ${directive}`, lineNum)
    }
  }

  if (!candidatesDeclared) {
    throw new ElectionError('no candidates')
  }

  return { candidates: candidateOrder, ballots }
}
"}

{"file_path":"src/count.js","content":"/**
 * Runs the instant-runoff count for a parsed election. Returns
 * `{ rounds, winner }` where each round is
 * `{ votes: Map<name, count>, exhausted, eliminated }`, `eliminated` being
 * the eliminated candidate's name or `null`, and `winner` is the winning
 * candidate's name or `null` when nobody wins.
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null
  const totalCount = ballots.reduce((s, b) => s + b.count, 0)

  while (true) {
    const votes = new Map()
    for (const c of continuing) votes.set(c, 0)
    let activeTotal = 0

    for (const b of ballots) {
      const target = b.names.find((n) => continuing.has(n))
      if (target !== undefined) {
        votes.set(target, votes.get(target) + b.count)
        activeTotal += b.count
      }
    }

    const exhausted = totalCount - activeTotal
    history.push(votes)

    if (activeTotal === 0) {
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    let roundWinner = null
    for (const [name, v] of votes) {
      if (v * 2 > activeTotal) {
        roundWinner = name
        break
      }
    }

    if (roundWinner !== null) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = roundWinner
      break
    }

    let minV = Infinity
    for (const v of votes.values()) if (v < minV) minV = v
    const tied = [...continuing].filter((c) => votes.get(c) === minV)
    const eliminated = tiebreak(tied, history)

    rounds.push({ votes, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

function tiebreak(tiedInit, history) {
  let tied = tiedInit
  if (tied.length === 1) return tied[0]

  while (true) {
    let splitFound = false
    for (const votesMap of history) {
      const vals = tied.map((c) => votesMap.get(c))
      const allEqual = vals.every((v) => v === vals[0])
      if (!allEqual) {
        const minV = Math.min(...vals)
        tied = tied.filter((c) => votesMap.get(c) === minV)
        splitFound = true
        break
      }
    }
    if (!splitFound || tied.length === 1) break
  }

  if (tied.length === 1) return tied[0]
  return tied.reduce((a, b) => (a > b ? a : b))
}
"}

{"file_path":"src/format.js","content":"/**
 * Formats one round's `round K: ...` line, listing continuing candidates by
 * descending vote count, and by ascending name where counts tie.
 */
export function formatRoundLine(roundNum, votes, exhausted) {
  const entries = [...votes.entries()]
  entries.sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  const parts = entries.map(([name, v]) => `${name}=${v}`)
  parts.push(`exhausted=${exhausted}`)
  return `round ${roundNum}: ${parts.join(' ')}`
}

/** Formats the final `winner <name>` or `no winner` line. */
export function formatWinnerLine(winner) {
  return winner !== null ? `winner ${winner}` : 'no winner'
}
"}

