export function colToNum(letters) {
  let n = 0
  const s = letters.toUpperCase()
  for (let i = 0; i < s.length; i++) {
    n = n * 26 + (s.charCodeAt(i) - 64)
  }
  return n
}

export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

const ADDR_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

// Parses a word as a candidate cell address. Returns { valid, col, row, key }.
// valid is false both for words that don't match the address shape and for
// words that match the shape but name a row of 0 (outside range).
export function parseAddressWord(word) {
  const m = ADDR_RE.exec(word)
  if (!m) return { valid: false }
  const letters = m[1].toUpperCase()
  const row = parseInt(m[2], 10)
  if (row < 1) return { valid: false }
  const col = colToNum(letters)
  return { valid: true, col, row, key: letters + String(row) }
}

export function compareAddrParts(a, b) {
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}

export function compareKeys(keyA, keyB) {
  const a = parseAddressWord(keyA)
  const b = parseAddressWord(keyB)
  return compareAddrParts(a, b)
}

// Enumerate the cell keys of a rectangle in ascending column then row order,
// regardless of which corner each endpoint was.
export function rectangleKeys(from, to) {
  const colMin = Math.min(from.col, to.col)
  const colMax = Math.max(from.col, to.col)
  const rowMin = Math.min(from.row, to.row)
  const rowMax = Math.max(from.row, to.row)
  const keys = []
  for (let c = colMin; c <= colMax; c++) {
    const letters = numToCol(c)
    for (let r = rowMin; r <= rowMax; r++) {
      keys.push(letters + String(r))
    }
  }
  return keys
}
"}

