    let survivors = [...continuing].filter((c) => votes.get(c) === fewest)

    if (survivors.length > 1) {
      for (let r = 0; r < rounds.length && survivors.length > 1; r++) {
        const roundVotes = rounds[r].votes
        const values = survivors.map((c) => roundVotes.get(c))
        const allEqual = values.every((v) => v === values[0])
        if (!allEqual) {
          let min = values[0]
          for (const v of values) if (v < min) min = v
          survivors = survivors.filter((c) => roundVotes.get(c) === min)
        }
      }
    }

    let eliminated
    if (survivors.length === 1) {
      eliminated = survivors[0]
    } else {
      eliminated = survivors.reduce((a, b) => (a > b ? a : b))
    }

    rounds[rounds.length - 1].eliminated = eliminated
    continuing = new Set([...continuing].filter((c) => c !== eliminated))
  }

  return { rounds, winner }
}
"}

{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection, ParseError } from './parse.js'
import { runElection } from './count.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'rounds' && argv[0] !== 'tally')) {
    fail('usage: cli.js rounds|tally')
  }
  const mode = argv[0]

  const input = readFileSync(0, 'utf8')

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      if (err.line === null || err.line === undefined) {
        fail(err.message)
      } else {
        fail(`line ${err.line}: ${err.message}`)
      }
      return
    }
    throw err
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)

  const out = []
  if (mode === 'rounds') {
    for (let i = 0; i < rounds.length; i++) {
      const round = rounds[i]
      const entries = [...round.votes.entries()]
      entries.sort((a, b) => {
        if (a[1] !== b[1]) return a[1] > b[1] ? -1 : 1
        return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
      })
      const parts = entries.map(([name, count]) => `${name}=${count}`)
      parts.push(`exhausted=${round.exhausted}`)
      out.push(`round ${i + 1}: ${parts.join(' ')}`)
      if (round.eliminated !== null) {
        out.push(`eliminated ${round.eliminated}`)
      }
    }
  } else {
    out.push(`rounds ${rounds.length}`)
  }

  out.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(out.join('\n') + '\n')
}

main()
"}

