 * RFC 3986 generic-syntax parsing, normalization and reference resolution.
 */

export class UriError extends Error {}

function isHexDigit(c) {
  return c !== undefined && /[0-9A-Fa-f]/.test(c)
}

function asciiLower(str) {
  let out = ''
  for (const c of str) {
    if (c >= 'A' && c <= 'Z') out += c.toLowerCase()
    else out += c
  }
  return out
}

/**
 * Parse a URI reference into its generic-syntax components. Presence and
 * emptiness are tracked separately for every optional component.
 */
export function parse(str) {
  let i = 0
  let hasScheme = false
  let scheme

  for (let j = 0; j < str.length; j++) {
    const c = str[j]
    if (c === ':') {
      hasScheme = true
      scheme = str.slice(0, j)
      i = j + 1
      break
    }
    if (c === '/' || c === '?' || c === '#') break
  }

  let hasAuthority = false
  let userinfoPresent = false
  let userinfo
  let host = ''
  let portPresent = false
  let port

  if (str.slice(i, i + 2) === '//') {
    i += 2
    const start = i
    while (i < str.length && str[i] !== '/' && str[i] !== '?' && str[i] !== '#') i++
    const authority = str.slice(start, i)
    hasAuthority = true

    const atIdx = authority.lastIndexOf('@')
    let hostport
    if (atIdx !== -1) {
      userinfoPresent = true
      userinfo = authority.slice(0, atIdx)
      hostport = authority.slice(atIdx + 1)
    } else {
      hostport = authority
    }

    const bracketIdx = hostport.lastIndexOf(']')
    const searchFrom = bracketIdx === -1 ? 0 : bracketIdx
    const colonIdx = hostport.indexOf(':', searchFrom)
    if (colonIdx !== -1) {
      portPresent = true
      host = hostport.slice(0, colonIdx)
      port = hostport.slice(colonIdx + 1)
    } else {
      host = hostport
    }
  }

  const pathStart = i
  while (i < str.length && str[i] !== '?' && str[i] !== '#') i++
  const path = str.slice(pathStart, i)

  let hasQuery = false
  let query
  if (str[i] === '?') {
    i++
    const qStart = i
    while (i < str.length && str[i] !== '#') i++
    hasQuery = true
    query = str.slice(qStart, i)
  }

  let hasFragment = false
  let fragment
  if (str[i] === '#') {
    i++
    fragment = str.slice(i)
    hasFragment = true
  }

  return {
    hasScheme, scheme,
    hasAuthority, userinfoPresent, userinfo, host, portPresent, port,
    path,
    hasQuery, query,
    hasFragment, fragment,
  }
}

export function serialize(u) {
  let s = ''
  if (u.hasScheme) s += u.scheme + ':'
  if (u.hasAuthority) {
    s += '//'
    if (u.userinfoPresent) s += u.userinfo + '@'
    s += u.host
    if (u.portPresent) s += ':' + u.port
  }
  s += u.path
  if (u.hasQuery) s += '?' + u.query
  if (u.hasFragment) s += '#' + u.fragment
  return s
}

function hasTruncatedPercent(str) {
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '%') {
      if (!isHexDigit(str[i + 1]) || !isHexDigit(str[i + 2])) return true
    }
  }
  return false
}

/**
 * Throw a UriError naming the first component (in the order path, userinfo,
 * host, query, fragment) that carries a truncated percent-encoding.
 */
export function checkTruncation(u) {
  const candidates = [
    ['path', u.path],
    ['userinfo', u.userinfoPresent ? u.userinfo : null],
    ['host', u.hasAuthority ? u.host : null],
    ['query', u.hasQuery ? u.query : null],
    ['fragment', u.hasFragment ? u.fragment : null],
  ]
  for (const [name, val] of candidates) {
    if (val == null) continue
    if (hasTruncatedPercent(val)) {
      throw new UriError(`the ${name} has a truncated percent-encoding`)
    }
