/** Normalize an already-parsed URI reference per the task's ordered rules. */
export function normalize(u) {
  const out = { ...u }

  if (out.hasScheme) out.scheme = asciiLower(out.scheme)

  out.path = decodePercent(out.path)
  if (out.userinfoPresent) out.userinfo = decodePercent(out.userinfo)
  if (out.hasAuthority) out.host = decodePercent(out.host)
  if (out.hasQuery) out.query = decodePercent(out.query)
  if (out.hasFragment) out.fragment = decodePercent(out.fragment)

  if (out.hasAuthority) out.host = asciiLower(out.host)

  if (out.portPresent) {
    const def = out.hasScheme ? DEFAULT_PORTS[out.scheme] : undefined
    if (out.port === '' || (def !== undefined && out.port === def)) {
      out.portPresent = false
      out.port = undefined
    }
  }

  out.path = removeDotSegments(out.path)

  if (out.hasAuthority && out.path === '') out.path = '/'

  return out
