      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      removeLastSegment()
    } else if (input === '/..') {
      input = '/'
      removeLastSegment()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      let idx = input[0] === '/' ? 1 : 0
      let nextSlash = input.indexOf('/', idx)
      if (nextSlash === -1) nextSlash = input.length
      output += input.slice(0, nextSlash)
      input = input.slice(nextSlash)
    }
  }

  return output
}

function mergePaths(base, refPath) {
  if (base.hasAuthority && base.path === '') return '/' + refPath
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

function copyAuthority(target, src) {
  target.userinfoPresent = src.userinfoPresent
  target.userinfo = src.userinfo
  target.host = src.host
  target.portPresent = src.portPresent
  target.port = src.port
}

/** RFC 3986 section 5.2.2, strict variant. `base` must have a scheme. */
export function resolve(base, ref) {
  const target = {}

  if (ref.hasScheme) {
    target.hasScheme = true
    target.scheme = ref.scheme
    target.hasAuthority = ref.hasAuthority
    if (ref.hasAuthority) copyAuthority(target, ref)
    target.path = removeDotSegments(ref.path)
    target.hasQuery = ref.hasQuery
    target.query = ref.query
  } else if (ref.hasAuthority) {
    target.hasAuthority = true
    copyAuthority(target, ref)
    target.path = removeDotSegments(ref.path)
    target.hasQuery = ref.hasQuery
    target.query = ref.query
    target.hasScheme = true
    target.scheme = base.scheme
  } else if (ref.path === '') {
    target.hasAuthority = base.hasAuthority
    if (base.hasAuthority) copyAuthority(target, base)
    target.path = base.path
    if (ref.hasQuery) {
      target.hasQuery = true
      target.query = ref.query
    } else {
      target.hasQuery = base.hasQuery
      target.query = base.query
    }
    target.hasScheme = true
    target.scheme = base.scheme
  } else {
    if (ref.path.startsWith('/')) {
      target.path = removeDotSegments(ref.path)
    } else {
      target.path = removeDotSegments(mergePaths(base, ref.path))
    }
    target.hasAuthority = base.hasAuthority
    if (base.hasAuthority) copyAuthority(target, base)
    target.hasQuery = ref.hasQuery
    target.query = ref.query
    target.hasScheme = true
    target.scheme = base.scheme
  }

  target.hasFragment = ref.hasFragment
  target.fragment = ref.fragment

  return target
