{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parse, serialize, normalize, resolve, checkTruncation, UriError } from './uri.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require_fs()
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.slice(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function require_fs() {
  // eslint-disable-next-line global-require
  return require('node:fs')
}

function fail(lineNumber, message) {
  const prefix = lineNumber === undefined ? 'error: ' : `error: line ${lineNumber}: `
  process.stderr.write(prefix + message + '\n')
  process.exit(2)
}

function processNormalize(line) {
  const u = parse(line)
  checkTruncation(u)
  return serialize(normalize(u))
}

function processResolve(line, lineNumber) {
  const idx = line.indexOf(' ')
  if (idx === -1) {
    fail(lineNumber, 'expected a base and a reference')
  }
  const baseStr = line.slice(0, idx)
  const refStr = line.slice(idx + 1)

  const base = parse(baseStr)
  if (!base.hasScheme) {
    fail(lineNumber, 'the base has no scheme')
  }
  checkTruncation(base)

  const ref = parse(refStr)
  checkTruncation(ref)

  const resolved = resolve(base, ref)
  return serialize(normalize(resolved))
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = readStdin()
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const results = []
  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    try {
      if (mode === 'normalize') {
        results.push(processNormalize(lines[i]))
      } else {
        results.push(processResolve(lines[i], lineNumber))
      }
    } catch (err) {
      if (err instanceof UriError) {
        fail(lineNumber, err.message)
      }
      throw err
    }
  }

  process.stdout.write(results.map((r) => r + '\n').join(''))
  process.exit(0)
}

main()
"}

