{"file_path":"src/parser.js","content":"// Parses a limiter file into policy definitions, routes and events.

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

export class ParseError extends Error {
  constructor(line, reason) {
    super(reason)
    this.line = line
  }
}

function splitLines(input) {
  if (input === '') return []
  const parts = input.split('\n')
  if (parts[parts.length - 1] === '') parts.pop()
  return parts
}

function parseIntField(token, field, least, lineNum) {
  if (!INT_RE.test(token)) {
    throw new ParseError(lineNum, `${field} must be an integer of at least ${least}`)
  }
  const value = BigInt(token)
  if (value < least) {
    throw new ParseError(lineNum, `${field} must be an integer of at least ${least}`)
  }
  return value
}

export function parseFile(input) {
  const lines = splitLines(input)
  const policies = new Map()
  const routes = new Map()
  const events = []
  let seenEvent = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1
    const raw = lines[i]
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'bucket') {
      if (seenEvent) throw new ParseError(lineNum, 'declarations must come before the first event')
      if (tokens.length !== 5) throw new ParseError(lineNum, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capTok, refillTok, perTok] = tokens
      if (!NAME_RE.test(name)) throw new ParseError(lineNum, `invalid policy name ${name}`)
      const capacity = parseIntField(capTok, 'capacity', 1n, lineNum)
      const refill = parseIntField(refillTok, 'refill', 0n, lineNum)
      const per = parseIntField(perTok, 'per', 1n, lineNum)
      if (policies.has(name)) throw new ParseError(lineNum, `policy ${name} is declared twice`)
      policies.set(name, { type: 'bucket', capacity, refill, per })
    } else if (directive === 'window') {
      if (seenEvent) throw new ParseError(lineNum, 'declarations must come before the first event')
      if (tokens.length !== 4) throw new ParseError(lineNum, 'expected window <name> <limit> <span>')
      const [, name, limitTok, spanTok] = tokens
      if (!NAME_RE.test(name)) throw new ParseError(lineNum, `invalid policy name ${name}`)
      const limit = parseIntField(limitTok, 'limit', 0n, lineNum)
      const span = parseIntField(spanTok, 'span', 1n, lineNum)
      if (policies.has(name)) throw new ParseError(lineNum, `policy ${name} is declared twice`)
      policies.set(name, { type: 'window', limit, span })
    } else if (directive === 'route') {
      if (seenEvent) throw new ParseError(lineNum, 'declarations must come before the first event')
      if (tokens.length < 3) throw new ParseError(lineNum, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      if (!NAME_RE.test(prefix)) throw new ParseError(lineNum, `invalid route prefix ${prefix}`)
      for (const pname of policyNames) {
        if (!policies.has(pname)) throw new ParseError(lineNum, `unknown policy ${pname}`)
      }
      if (routes.has(prefix)) throw new ParseError(lineNum, `prefix ${prefix} is routed twice`)
      routes.set(prefix, policyNames)
    } else if (directive === 'event') {
      if (tokens.length !== 3) throw new ParseError(lineNum, 'expected event <tick> <key>')
      const [, tickTok, key] = tokens
      const tick = parseIntField(tickTok, 'tick', 0n, lineNum)
      if (!NAME_RE.test(key)) throw new ParseError(lineNum, `invalid key ${key}`)
      if (lastTick !== null && tick < lastTick) {
        throw new ParseError(lineNum, `tick ${tick} is before tick ${lastTick}`)
      }
      lastTick = tick
      seenEvent = true
      events.push({ tick, key })
    } else {
      throw new ParseError(lineNum, `unknown directive ${directive}`)
    }
  }

  return { policies, routes, events }
}
"}

