{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { parseGraph, ParseError } from './parse.js'
import { detectCycle, computeTimings, CycleError } from './graph.js'
import { packSchedule } from './pack.js'

const WORKERS_RE = /^[1-9][0-9]*$/

function usageError() {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fs = require ? null : null
  return null
}

async function readStdinAsync() {
  const chunks = []
  for await (const chunk of process.stdin) chunks.push(chunk)
  return Buffer.concat(chunks.map((c) => (Buffer.isBuffer(c) ? c : Buffer.from(c)))).toString('utf8')
}

async function main() {
  const args = process.argv.slice(2)

  let mode
  let workerCount = null

  if (args.length === 1 && (args[0] === 'waves' || args[0] === 'explain')) {
    mode = args[0]
  } else if (args.length === 2 && args[0] === 'pack') {
    mode = 'pack'
    if (!WORKERS_RE.test(args[1])) {
      process.stderr.write('error: workers must be a positive integer\n')
      process.exit(2)
    }
    workerCount = parseInt(args[1], 10)
  } else {
    usageError()
    return
  }

  const input = await readStdinAsync()

  let tasks
  let deps
  try {
    ;({ tasks, deps } = parseGraph(input))
  } catch (err) {
    if (err instanceof ParseError) {
      process.stderr.write(err.message + '\n')
      process.exit(2)
    }
    throw err
  }

  try {
    detectCycle(tasks, deps)
  } catch (err) {
    if (err instanceof CycleError) {
      process.stderr.write(err.message + '\n')
      process.exit(3)
    }
    throw err
  }

  if (mode === 'waves') {
    const { finish, depth } = computeTimings(tasks, deps)
    const waves = new Map()
    for (const name of tasks.keys()) {
      const d = depth.get(name)
      if (!waves.has(d)) waves.set(d, [])
      waves.get(d).push(name)
    }
    const maxDepth = waves.size > 0 ? Math.max(...waves.keys()) : -1
    let out = ''
    for (let k = 0; k <= maxDepth; k++) {
      const names = (waves.get(k) || []).slice().sort()
      out += `wave ${k}: ${names.join(' ')}\n`
    }
    let total = 0
    for (const f of finish.values()) if (f > total) total = f
    out += `total ${total}\n`
    process.stdout.write(out)
  } else if (mode === 'explain') {
    const { start, finish, depth } = computeTimings(tasks, deps)
    const names = Array.from(tasks.keys()).sort()
    let out = ''
    for (const name of names) {
      out += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
    }
    let total = 0
    for (const f of finish.values()) if (f > total) total = f
    out += `total ${total}\n`
    process.stdout.write(out)
  } else if (mode === 'pack') {
    const { workers, makespan } = packSchedule(tasks, deps, workerCount)
    let out = ''
    for (let i = 0; i < workers.length; i++) {
      const runs = workers[i].runs.map((r) => ` ${r.name}@${r.start}-${r.finish}`).join('')
      out += `worker ${i}:${runs}\n`
    }
    out += `makespan ${makespan}\n`
    process.stdout.write(out)
  }
}

main()
"}

